// The armory page: helmets, shields and swords in stock.
angular.module("castra.core")
    .component("armoryPage", {
        templateUrl: "app/ajs/features/armory/armory-page.html",
        controller : Controller
    });

Controller.$inject = [ "armoryService", "$state" ];

function Controller (armoryService, $state) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.counting = false;
        armoryService.inventory().then(function (items) {
            $ctrl.items = items;
            $ctrl.shields = items.shields;
            $ctrl.gladii = items.gladii;
        });
    };

