// The AngularJS core module. Every Angular component and service that AngularJS code may use is downgraded here.
import * as angular from "angular";
import { downgradeComponent, downgradeInjectable } from "@angular/upgrade/static";
import { CampAlertComponent } from "../../features/camp/camp-alert.component";
import { DateStampComponent } from "../../features/camp/date-stamp.component";
import { FeatureFlags } from "../../features/camp/feature-flags.service";
import { LoadingSpinnerComponent } from "../../features/camp/loading-spinner.component";
import { NotificationHub } from "../../features/camp/notification-hub.service";
import { CohortStore } from "../../features/legions/cohort.store";
import { LegionBadgeComponent } from "../../features/legions/legion-badge.component";
import { RankInsigniaComponent } from "../../features/legions/rank-insignia.component";
import { RollCallComponent } from "../../features/legions/roll-call.component";
import { RationCardComponent } from "../../features/rations/ration-card.component";
import { SupplyMeterComponent } from "../../features/rations/supply-meter.component";
import { SupplyService } from "../../features/rations/supply.service";
import { DenariiAmountComponent } from "../../features/treasury/denarii-amount.component";
import { TreasuryPageComponent } from "../../features/treasury/treasury-page.component";

angular.module("castra.core", [])
    .directive("rationCard", downgradeComponent({ component: RationCardComponent }) as angular.IDirectiveFactory)
    .directive("supplyMeter", downgradeComponent({ component: SupplyMeterComponent }) as angular.IDirectiveFactory)
    .directive("treasuryPage", downgradeComponent({ component: TreasuryPageComponent }) as angular.IDirectiveFactory)
    .directive("denariiAmount", downgradeComponent({ component: DenariiAmountComponent }) as angular.IDirectiveFactory)
    .directive("legionBadge", downgradeComponent({ component: LegionBadgeComponent }) as angular.IDirectiveFactory)
    .directive("rollCall", downgradeComponent({ component: RollCallComponent }) as angular.IDirectiveFactory)
    .directive("rankInsignia", downgradeComponent({ component: RankInsigniaComponent }) as angular.IDirectiveFactory)
    .directive("campAlert", downgradeComponent({ component: CampAlertComponent }) as angular.IDirectiveFactory)
    .directive("dateStamp", downgradeComponent({ component: DateStampComponent }) as angular.IDirectiveFactory)
    .directive("loadingSpinner", downgradeComponent({ component: LoadingSpinnerComponent }) as angular.IDirectiveFactory)
    .factory("supplyService", downgradeInjectable(SupplyService))
    .factory("cohortStore", downgradeInjectable(CohortStore))
    .factory("notificationHub", downgradeInjectable(NotificationHub))
    .factory("featureFlags", downgradeInjectable(FeatureFlags));
